class Solution:
    def minInsertions(self, s: str) -> int:
        while "()" in s:
            s = s.replace("()", "")
        return len(s)

code.java:
class Solution {
    public int minInsertions(String s) {
        while (s.contains("()")) s = s.replace("()", "");
        return s.length();
    }
}

code.cpp:
class Solution {
public:
    int minInsertions(string& s) {
        string t = s;
        size_t i;
        while ((i = t.find("()")) != string::npos) t.erase(i, 2);
        return t.size();
    }
};

code.c:
int minInsertions(char* s) {
    int n = strlen(s);
    char* t = malloc(n + 1);
    memcpy(t, s, n + 1);
    bool changed = true;
    while (changed) {
        changed = false;
        int w = 0;
        for (int i = 0; t[i]; i++) {
            if (t[i] == '(' && t[i + 1] == ')') { i++; changed = true; continue; }
            t[w++] = t[i];
        }
        t[w] = '\0';
    }
    int left = strlen(t);
    free(t);
    return left;
}

