class Solution:
    def minInsertions(self, s: str) -> int:
        open_, added = 0, 0
        for c in s:
            if c == "(":
                open_ += 1
            elif open_:
                open_ -= 1
            else:
                added += 1
        return added + open_

code.java:
class Solution {
    public int minInsertions(String s) {
        int open = 0, added = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') open++;
            else if (open > 0) open--;
            else added++;
        }
        return added + open;
    }
}

